window.products.push({"id":1220641,"name":"Peanuts Snoopy 14K Gold Earrings - Gold/Pavé","category":"jewelry","retail price":68.0,"sale price":null,"image":"https://cdn.shopify.com/s/files/1/0267/5746/4148/files/152190_G_01_RS_SQ_2026_0c8f8781-179b-4dbf-a3a6-d1781bd75b8e.jpg?v=1784196791","description":"Add a little Snoopy to your everyday. These huggie earrings capture everyone’s favorite beagle in a sleek silhouette that's perfect for fans of all ages. Gold huggies with Snoopy’s face, covered with bright cubic zirconia stones Crafted with 14k gold plated sterling silver Lightweight and easy to wear — whether worn solo or in a conversation-starting earstack Sweet, nostalgic, and full of charm, these earrings bring a touch of Peanuts to every outfit. This is an officially licensed Peanuts product.","images":["https://cdn.shopify.com/s/files/1/0267/5746/4148/files/152190_G_01_RS_SQ_2026_0c8f8781-179b-4dbf-a3a6-d1781bd75b8e.jpg?v=1784196791","https://cdn.shopify.com/s/files/1/0267/5746/4148/files/174620_SS_01_SQ.jpg?v=1786566813","https://cdn.shopify.com/s/files/1/0267/5746/4148/files/174624_SS_01_SQ.jpg?v=1786566844","https://cdn.shopify.com/s/files/1/0267/5746/4148/files/174623_SS_01_SQ.jpg?v=1786566838","https://cdn.shopify.com/s/files/1/0267/5746/4148/files/174622_SS_01_SQ.jpg?v=1786566830","https://cdn.shopify.com/s/files/1/0267/5746/4148/files/174621_SS_01_SQ.jpg?v=1786566824"],"specifications":{"brand":"SuperFan by BaubleBar","product_type":"Earrings","source_store":"baublebar.com","source_variant_id":"43382571270228"},"sku":"BM-1220641","productType":"Jewelry","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://baublebar.com/products/peanuts-snoopy-14k-gold-earrings","source_catalog":"Public Shopify online-store product feed","source_store":"baublebar.com","source_handle":"peanuts-snoopy-14k-gold-earrings","source_variant_id":"43382571270228","price_pending":true,"merchant_ready":false});
